mapper.select:
SELECT cd.course_id, cd.destination_id, cd.visit_order, COALESCE(dt.name, '이름 없는 여행지') AS destination_name, COALESCE( ( SELECT di.image_url FROM destination_images di WHERE di.destination_id = d.id AND di.is_main = 1 ORDER BY di.order_index ASC, di.id ASC LIMIT 1 ), ( SELECT di.image_url FROM destination_images di WHERE di.destination_id = d.id ORDER BY di.order_index ASC, di.id ASC LIMIT 1 ) ) AS image_url FROM course_destinations cd JOIN destinations d ON d.id = cd.destination_id JOIN courses c ON c.id = cd.course_id AND c.deleted = 0 AND c.status = 'PUBLISHED' LEFT JOIN destination_translations dt ON dt.destination_id = d.id AND dt.language_code = 'ko' WHERE cd.course_id IN
#{courseId}
ORDER BY cd.course_id ASC, cd.visit_order ASC, cd.id ASC

mapper.insert:
INSERT INTO course_destinations (
    course_id, destination_id, visit_order
) VALUES (
             #{courseId}, #{destinationId}, #{visitOrder}
         )

mapper.select:
SELECT DISTINCT course_id
FROM course_destinations
WHERE destination_id = #{destinationId}

mapper.update:
UPDATE course_destinations
SET visit_order = #{visitOrder}
WHERE id = #{id}

UPDATE courses
SET deleted = 1,
    deleted_at = NOW()
WHERE id = #{courseId}
  AND user_id = #{userId}
  AND deleted = 0
